// FIFO module
module fifo #(
		parameter WIDTH = 32,
		parameter DEPTH = 16
	) (
		input wire clk,
		input wire rst,
		input wire wr_en,
		input wire rd_en,
		input wire [WIDTH-1 : 0] din,
		output reg [WIDTH-1 : 0] dout,
		output wire full,
		output wire empty,
		output wire wr_rst_busy,
		output wire rd_rst_busy,
		output wire wr_ack,
		output wire rd_ack
	);

	localparam ADDR_WIDTH = $clog2(DEPTH);

	reg [WIDTH-1 : 0] mem [0 : DEPTH-1];
	reg [ADDR_WIDTH-1 : 0] wr_ptr, rd_ptr;
	reg [ADDR_WIDTH : 0] count;

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			wr_ptr <= 0;
			rd_ptr <= 0;
			count <= 0;
			wr_rst_busy <= 1'b1;
			rd_rst_busy <= 1'b1;
		end else begin
			wr_rst_busy <= 1'b0;
			rd_rst_busy <= 1'b0;

			if (wr_en && !full) begin
				mem[wr_ptr] <= din;
				wr_ptr <= wr_ptr + 1;
				count <= count + 1;
			end

			if (rd_en && !empty) begin
				dout <= mem[rd_ptr];
				rd_ptr <= rd_ptr + 1;
				count <= count - 1;
			end
		end
	end

	assign full = (count == DEPTH);
	assign empty = (count == 0);
	assign wr_ack = wr_en && !full;
	assign rd_ack = rd_en && !empty;

endmodule
